import re


def eval_expression(expr):
    """Evaluate an arithmetic expression containing +, -, *, /, and parentheses."""

    token_pattern = re.compile(r"\s*(?:(\d+(?:\.\d*)?|\.\d+)|([()+\-*/]))")
    tokens = []
    position = 0

    while position < len(expr):
        match = token_pattern.match(expr, position)

        if not match:
            if expr[position:].strip() == "":
                break
            raise ValueError(f"Invalid character at position {position}")

        number, operator = match.groups()
        if number is not None:
            tokens.append(float(number) if "." in number else int(number))
        else:
            tokens.append(operator)

        position = match.end()

    index = 0

    def parse_expression():
        nonlocal index
        value = parse_term()

        while index < len(tokens) and tokens[index] in ("+", "-"):
            operator = tokens[index]
            index += 1
            right = parse_term()
            value = value + right if operator == "+" else value - right

        return value

    def parse_term():
        nonlocal index
        value = parse_factor()

        while index < len(tokens) and tokens[index] in ("*", "/"):
            operator = tokens[index]
            index += 1
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor():
        nonlocal index

        if index >= len(tokens):
            raise ValueError("Unexpected end of expression")

        token = tokens[index]

        # Handle unary plus and minus, including negative numbers.
        if token == "+":
            index += 1
            return parse_factor()

        if token == "-":
            index += 1
            return -parse_factor()

        if token == "(":
            index += 1
            value = parse_expression()

            if index >= len(tokens) or tokens[index] != ")":
                raise ValueError("Missing closing parenthesis")

            index += 1
            return value

        if isinstance(token, (int, float)):
            index += 1
            return token

        raise ValueError(f"Unexpected token: {token}")

    if not tokens:
        raise ValueError("Expression is empty")

    result = parse_expression()

    if index != len(tokens):
        raise ValueError(f"Unexpected token: {tokens[index]}")

    return result
